            max_record_bytes: 1_048_576,
            max_held_bytes: 4 * 1_048_576,
            max_hold: Duration::from_secs(300),
            decide_timeout: Duration::from_secs(5),
            keepalive: Duration::from_secs(10),
            on_failure: OnFailure::Block,
        }
    }
}

