        assert_eq!(l.max_hold, Duration::from_secs(300));
        assert_eq!(l.decide_timeout, Duration::from_secs(5));
        assert_eq!(l.keepalive, Duration::from_secs(10));
        assert_eq!(l.on_failure, OnFailure::Block);
    }
}
