const DATA_KEYS: &[&str] = &["input", "input_schema", "parameters"];

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Envelope,
    Data,
}

fn parse_with(bytes: &[u8], mode: Mode) -> Result<Value, Malformed> {
    let mut de = serde_json::Deserializer::from_slice(bytes);
