const CLASSIFIER_KEYS: &[&str] = &[
    "arguments",
    "choices",
    "chunk",
    "content",
    "content_block",
    "custom",
    "delta",
    "error",
    "finish_reason",
    "function",
    "function_call",
    "functions",
    "id",
