const PROTOTYPE_KEYS: &[&str] = &["__proto__", "constructor", "prototype"];

fn fold(s: &str) -> String {
    s.chars()
        .flat_map(|c| match c {
            '\u{0130}' | '\u{0131}' => 'i'.to_lowercase(),
            '\u{017F}' => 's'.to_lowercase(),
            '\u{212A}' => 'k'.to_lowercase(),
            c => c.to_lowercase(),
        })
