        }
        files.push((root().join(format!("golden/{fmt}/{name}.sse")), o.out));
        manifest.push(json!({"file": format!("{fmt}/{name}.sse"), "format": fmt, "allowed": allowed, "notices": notices, "notice_choices": notice_choices, "finish_reasons": finish}));
